NAME = 'NlCanisius1939: Petrus Canisius Translation'
BOOK = 'Hebrews'

CHAPTERS = {
    1: {
        1: 'Nadat God eertijds vele malen en op velerlei wijzen tot de Vaders gesproken heeft door de Profeten,',
        2: 'heeft Hij aan het einde dezer dagen tot ons gesproken door den Zoon, dien Hij gesteld heeft tot erfgenaam van al zijn bezit en door wien Hij de wereld gemaakt heeft.',
        3: 'Deze is de afstraling zijner Glorie en de afdruk van zijn Wezen, en Hij draagt het heelal door het woord zijner Macht; Hij heeft de reiniging van zonden bewerkt, en toen Zich neergezet aan de rechterhand der Majesteit in den hoge.',
        4: 'Even hoog staat Hij boven de engelen, als de Naam, die Hij ontving, voortreffelijker is dan de hunne.',
        5: 'Want tot wien der engelen heeft Hij ooit gezegd: "Gij zijt mijn Zoon, Ik heb U heden verwekt." Of wederom: "Ik zal Hem tot Vader zijn, En Hij zal Mij wezen tot Zoon."',
        6: 'En wanneer Hij den Eerstgeborene de wereld binnenleidt, zegt Hij opnieuw: "Alle engelen Gods moeten Hem aanbidden."',
        7: 'En van de engelen zegt Hij: "Die zijn engelen geesten maakt, En zijn knechten vlammend vuur."',
        8: 'Maar van den Zoon: Uw troon, o God, is in de eeuwen der eeuwen, En uw koningschepter is de schepter van het recht.',
        9: 'Gij hebt gerechtigheid bemind, En ongerechtigheid gehaat. Daarom, o God, heeft uw God U gezalfd, Met vreugde-olie boven uw genoten.',
        10: 'En: Heer, in den beginne hebt Gij de aarde gegrond, En de hemelen zijn de werken uwer handen.',
        11: 'Zij zullen vergaan, maar Gij blijft! Als een kleed zullen ze allen verslijten.',
        12: 'Als een mantel rolt Gij ze op, En als een kleed zullen ze worden verwisseld. Maar Gij blijft dezelfde, En uw jaren nemen geen einde.',
        13: 'En tot wien der engelen sprak Hij ooit: "Zet U aan mijn rechterhand, Totdat Ik uw vijanden leg als een voetbank voor uw voeten."',
        14: 'Zijn ze niet allen dienstbare geesten, uitgezonden tot hulp van hen, die de zaligheid zullen beërven?',
    },
    2: {
        1: 'Daarom moeten we ons des te steviger vastklampen aan wat we gehoord hebben; anders toch drijven we weg.',
        2: 'Want zo het woord van kracht bleef, dat door de engelen werd verkondigd, en iedere overtreding en ongehoorzaamheid gerechte straf ontving:',
        3: 'hoe zullen wij dan ontkomen, wanneer we een zaligheid verwaarlozen, welke het eerst door den Heer is gepreekt, welke onder ons werd bevestigd door hen die Hem hoorden,',
        4: 'en welke ook door God is betuigd door tekenen, wonderen en velerlei kracht, door gaven ook van den heiligen Geest, zoals het Hem heeft behaagd?',
        5: 'Immers niet aan engelen onderwierp Hij de toekomstige wereld, waarover we spreken.',
        6: 'Want er is ergens getuigd: Wat is een mens, dat Gij hem zoudt gedenken, Of een mensenkind, dat Gij acht op hem slaat?',
        7: 'Een korte tijd hebt Gij hem beneden de engelen gesteld, Hem met glorie en luister gekroond.',
        8: 'Alles hebt Gij onderworpen aan zijn voeten. Door hem nu alles te onderwerpen, heeft Hij niets uitgezonderd, dat hem niet onderworpen is. Zeker, nu zien we nog niet, dat alles hem onderworpen is.',
        9: 'Maar wel zien we Jesus met glorie en luister gekroond, omdat Hij de dood heeft ondergaan; Hij, die een korte tijd beneden de engelen was gesteld, om door Gods genade de dood te smaken voor allen.',
        10: 'Het lag toch voor de hand, dat Hij, om wien en door wien alles bestaat, en die vele zonen tot glorie brengt, ook hun Leidsman ter zaligheid door lijden tot glorie zou brengen.',
        11: 'Want Hij die heiligt, en zij die geheiligd worden, zijn allen uit Eén. Daarom schaamt Hij Zich niet, hen broeders te noemen,',
        12: 'als Hij zegt: "Ik zal uw Naam aan mijn broeders verkondigen, In de kring der gemeente U prijzen."',
        13: 'En wederom: "Ik zal op Hem mijn betrouwen stellen." En vervolgens: "Zie Ik en de kinderen, Die God Mij gaf."',
        14: 'Welnu, omdat de kinderen deel hebben aan vlees en bloed, daarom was ook Hij daaraan deelachtig, om door de Dood hem machteloos te maken, die macht had over de dood, en dat is de duivel;',
        15: 'en om allen te verlossen, die uit vrees voor de dood heel hun leven in slavernij zouden verkeren.',
        16: 'Niet engelen toch trok Hij Zich aan, maar Abrahams zaad trok Hij Zich aan.',
        17: 'En daarom moest Hij in alles gelijk worden aan zijn broeders, opdat Hij in hun betrekkingen tot God een barmhartig en getrouw Hogepriester zou zijn tot uitboeting der zonde van het volk.',
        18: 'Want juist omdat Hijzelf werd bekoord en zelf heeft geleden, kan Hij ook hen helpen, die worden bekoord.',
    },
    3: {
        1: 'Heilige broeders, deelgenoten ener hemelse roeping, beschouwt dus den Apostel en Hogepriester onzer belijdenis: Jesus,',
        2: 'die getrouw is aan Hem, die Hem gemaakt heeft, zoals ook "Moses in geheel zijn huis."',
        3: 'Tegenover Moses is Hij immers in die mate groter eer waardig, als de bouwheer meer eer geniet dan het huis.',
        4: 'Elk huis toch wordt door iemand gebouwd; maar de Bouwheer van alles is God.',
        5: 'Moses nu was wel "getrouw in geheel zijn huis" als dienstknecht, om getuigenis af te leggen van wat verkondigd zou worden,',
        6: 'maar Christus is het als Zoon boven zijn huis; zijn huis zijn wij, indien wij de zekerheid der hoop en het roemen daarop ongeschokt bewaren ten einde toe.',
        7: 'Daarom zegt de heilige Geest: Als gij dan heden mijn stem verneemt,',
        8: 'Verstokt dan uw harten niet als bij de Verbittering, Als op de dag der Verzoeking in de woestijn,',
        9: 'Toen uw vaders Mij tartten en beproefden,',
        10: 'Ofschoon ze mijn werken hadden aanschouwd veertig jaar lang. Daarom werd Ik toornig op dat geslacht, En Ik sprak: Steeds dwaalt hun hart van Mij af, En mijn wegen kennen ze niet.',
        11: 'Daarom zwoer Ik in mijn toorn: Neen, ze zullen niet ingaan in mijn Rust!',
        12: 'Broeders, zorgt er voor, dat in niemand van u een boos en ongelovig hart wordt gevonden door de afval van den levenden God;',
        13: 'maar vermaant elkander iedere dag, zolang het "Heden" nog voortduurt, opdat niemand van u wordt verstokt door de verleiding der zonde.',
        14: 'Want we delen slechts met Christus mee, zo we de aanvankelijke overtuiging ongeschokt bewaren ten einde toe.',
        15: 'Wanneer er dus wordt gezegd: "Als gij dan heden mijn stem verneemt, verstokt uw harten niet als bij de Verbittering"',
        16: 'wie waren het dan, die vernamen en verbitterden? Waren het niet allen, die, dank zij Moses, Egypte waren uitgetrokken?',
        17: 'Of tegen wie toornde Hij veertig jaar lang? Was het niet tegen hen, die gezondigd hadden, wier lijken neerlagen in de woestijn?',
        18: 'En tegen wie anders heeft Hij gezworen, dat ze niet zouden ingaan in zijn Rust, dan juist tegen de ongehoorzamen?',
        19: 'Zo zien we, dat ze niet konden ingaan om hun ongeloof.',
    },
    4: {
        1: 'We moeten er dus wèl bevreesd voor zijn, dat iemand van u bevonden wordt achter te blijven, terwijl de belofte nog voortduurt, om zijn Rust binnen te gaan.',
        2: 'Immers ook wij hebben de belofte ontvangen, juist zoals zij. Maar hùn heeft het woord, dat ze hoorden, niet gebaat, omdat het horen niet gepaard ging met geloof;',
        3: 'want we gaan slechts binnen in de Rust, indien we geloven; zoals Hij heeft gezegd: "Daarom zwoer Ik in mijn toorn: neen, ze zullen niet ingaan in mijn Rust." —Inderdaad, toen door de schepping der wereld de werken voltooid waren,',
        4: 'heeft Hij over de zevende dag ergens aldus gesproken: "En God Rustte op de zevende dag van al zijn werken;"',
        5: 'en hier weer: "Neen, ze zullen niet ingaan in mijn Rust."',
        6: 'Welnu, daar het zeker is, dat enigen althans Haar zullen binnengaan, terwijl zij, die het eerst de belofte ontvingen, door ongehoorzaamheid er niet zijn binnengegaan,',
        7: 'daarom stelt Hij opnieuw een dag vast: "Heden", en spreekt Hij zo lange tijd daarna door David, zoals reeds gezegd is: "Als gij heden mijn stem verneemt, verstokt uw harten niet."',
        8: 'Zo Josuë immers de rust had gebracht, dan zou Hij niet van een andere dag spreken, die eerst later zou komen.',
        9: 'Dus is het volk Gods nog een Sabbat-Rust voorbehouden;',
        10: 'want die zijn Rust binnengaat, rust ook zelf van zijn werken, zoals ook God van de zijne.',
        11: 'Doen wij ons best dus, om binnen te gaan in die Rust, opdat niemand in dit voorbeeld van ongehoorzaamheid mag vervallen.',
        12: 'Want Gods woord is levend en krachtig, scherper dan elk tweesnijdend zwaard, dóórdringend tussen ziel en geest, gewrichten en merg, rechter ook der neigingen en overdenkingen van het hart.',
        13: 'En geen schepsel is onzichtbaar voor Hem, maar alles ligt naakt en bloot voor de ogen van Hem, aan wien we verantwoording hebben af te leggen.',
        14: 'Daar we nu een groten Hogepriester hebben, die in de hemelen is doorgedrongen, Jesus, den zoon van God, zo laat ons vasthouden aan de belijdenis.',
        15: 'Want we hebben geen Hogepriester, die onze zwakheden niet meevoelen kan, maar Eén, die bekoord werd geheel op dezelfde wijze als wij, behoudens de zonde.',
        16: 'Laat ons dus met vertrouwen opgaan tot de troon der genade, om barmhartigheid te verkrijgen, en genade te vinden tot tijdige hulp.',
    },
    5: {
        1: 'Want iedere hogepriester wordt uit de kring der mensen genomen, en ten bate der mensen aangesteld voor hun betrekkingen tot God, om gaven en offers te brengen voor de zonden.',
        2: 'Hij moet in staat wezen, toegeeflijk te zijn voor onwetenden en dwalenden, omdat hij zelf met zwakheid omkleed is,',
        3: 'en daarom zondeoffers moet brengen zowel voor het volk, als voor zichzelf.',
        4: 'En niemand neemt de waardigheid uit zichzelf, maar door roeping van God, zoals ook Aäron.',
        5: 'Zo ook heeft Christus Zichzelf de eer niet toegeëigend, Hogepriester te worden, maar Hij die tot Hem heeft gesproken: "Gij zijt mijn Zoon, Ik heb U heden verwekt,"',
        6: 'zoals Hij dan ook op een andere plaats heeft gezegd: "Gij zijt Priester voor eeuwig, Naar de Orde van Melkisedek."',
        7: 'En ofschoon Hij in de dagen van zijn Vlees, onder luid geroep en tranen, gebeden en smekingen heeft opgestierd tot Hem, die Hem van de dood kon redden; ofschoon Hij verhoord werd terwille van zijn godvrezendheid;',
        8: 'ofschoon Hij bovendien zelfs de Zoon was, heeft Hij toch door zijn lijden de gehoorzaamheid geleerd,',
        9: 'en is Hij na zijn verheerlijking de oorzaak van eeuwige zaligheid geworden voor allen, die Hem gehoorzaam zijn;',
        10: 'daar Hij door God was uitgeroepen tot "Hogepriester naar de Orde van Melkisedek."',
        11: 'Over dit onderwerp hebben we veel te zeggen, en de uitleg is moeilijk, omdat gij hardhorend zijt geworden.',
        12: 'Of is het soms nog nodig, dat men u de eerste beginselen van Gods woorden gaat leren, terwijl gij toch, de tijd in aanmerking genomen, reeds leermeesters moest zijn; hebt gij soms nog behoefte aan melk, niet aan vaste spijs?',
        13: 'Want wie nog melk behoeft, is onbekwaam voor het woord der gerechtigheid, want hij is een kind;',
        14: 'maar vaste spijs is voor de volwassenen, voor hen, die door oefening de zintuigen hebben afgericht, om goed en kwaad te onderscheiden.',
    },
    6: {
        1: 'Daarom willen we de aanvangsleer over Christus laten rusten en tot het volmaakte overgaan, zonder opnieuw een grondslag te leggen van: bekering uit dode werken, geloof in God,',
        2: 'de leer over doopsels, handoplegging, opstanding der doden en eeuwig oordeel.',
        3: 'En dit gaan we nu ondernemen, zo God het wil.',
        4: 'Want het is toch onmogelijk, om hen, die eenmaal verlicht zijn geweest, de hemelse gaven hebben gesmaakt, den heiligen Geest hebben ontvangen,',
        5: 'het heerlijk woord Gods en de krachten der toekomstige wereld hebben geproefd,',
        6: 'maar afgevallen zijn: het is onmogelijk, om hen een tweede maal tot bekering op te wekken, daar ze, zover het hùn betreft, den Zoon van God opnieuw hebben gekruisigd en bespot.',
        7: 'De bodem immers, die de overvloedig neervallende regen heeft opgezogen, en nuttig gewas voortbrengt voor hen, door wie hij werd bebouwd, hij ontvangt zegen van God;',
        8: 'maar zo hij doornen en distels voortbrengt, dan wordt hij afgekeurd en is de vloek nabij, die uitloopt op verbranding.',
        9: 'Maar al spreken we zó, geliefden, toch zijn we over u van iets beters overtuigd, iets dat tot zaligheid strekt.',
        10: 'Want God is niet onrechtvaardig; en Hij zal dus uw arbeid niet vergeten noch de liefde, die gij om zijn Naam hebt getoond door het dienen der heiligen vroeger en thans.',
        11: 'We wensen echter, dat gij allen dezelfde ijver aan de dag blijft leggen, om de volle zekerheid der hoop te bewaren ten einde toe;',
        12: 'en dat gij niet traag moogt worden, maar navolgers van hen, die door geloof en volharding de belofte hebben verkregen.',
        13: 'Want toen God aan Abraham de belofte deed, zwoer Hij bij Zichzelf, daar Hij bij geen hogere kon zweren en Hij sprak:',
        14: '"Voorwaar, rijk zal Ik u zegenen, Overvloedig u vermenigvuldigen,"',
        15: 'en zo verkreeg Abraham de vervulling der belofte door volharding.',
        16: 'De mensen toch zweren bij hem die hoger staat, en de eed dient hun tot bevestiging, en sluit verdere tegenspraak uit.',
        17: 'Daarom ook heeft God een eed tot waarborg gegeven, toen Hij aan de erfgenamen der belofte nog duidelijker de onveranderlijkheid van zijn Raadsbesluit wilde tonen;',
        18: 'opdat wij door twee onwrikbare zaken, waardoor het God onmogelijk is te bedriegen, een krachtige aansporing zouden ontvangen, om onze toevlucht te nemen en ons vast te klampen aan de hoop op wat ons is weggelegd.',
        19: 'Haar toch behouden we als een veilig en zeker anker onzer ziel, vastzittend in het binnenste achter het Voorhangsel,',
        20: 'waar terwille van ons onze Voorloper is binnengegaan: Jesus, "Hogepriester voor eeuwig naar de Orde van Melkisedek."',
    },
    7: {
        1: 'Deze Melkisedek immers was koning van Salem en priester van den allerhoogsten God; hij ging Abraham tegemoet, toen deze terugkeerde van zijn overwinning op de koningen, en hij zegende hem;',
        2: 'en Abraham gaf hem de tiende van alles. Welnu, vooreerst betekent zijn naam: Koning der Gerechtigheid; vervolgens was hij koning van Salem, en dit betekent: Koning van de Vrede;',
        3: 'ook was hij zonder vader, zonder moeder, zonder geslachtslijst, zonder begin van dagen en einde van leven; en zó is hij den Zoon van God volkomen gelijk geworden, blijft hij priester voor eeuwig.',
        4: 'Overweegt nu eens, hoe groot hij is, dat zelfs Abraham, de aartsvader, hem tiende gaf uit het beste van de buit.',
        5: 'Zeker, ook de zonen van Levi, die het priesterschap ontvingen, kregen volgens de Wet bevel, om tiende te heffen van het volk, dat is van hun broeders, ofschoon ook zij uit Abrahams lende waren voortgesproten.',
        6: 'Maar ofschoon Melkisedek niet tot hun geslacht behoorde, heeft hij toch tiende van Abraham ontvangen, en hem gezegend, die de belofte bezat.',
        7: 'Welnu, het lijdt geen tegenspraak, dat het mindere wordt gezegend door het meerdere;',
        8: 'en in het éne geval waren het sterflijke mensen, die tiende ontvingen, in het andere geval een, van wien getuigd wordt, dat hij leeft.',
        9: 'Bovendien heeft Levi, die zelf tiende hief, als ‘t ware in Abraham tiende betaald;',
        10: 'want hij was nog in de lende van zijn vader, toen Melkisedek dien tegemoet ging.',
        11: 'Zo dus de volmaaktheid bereikt was door het levietische priesterschap—want daarop berustte de wetgeving voor het volk waarom zou het dan nog nodig geweest zijn, dat er een andere Priester werd aangesteld "naar de Orde van Melkisedek," en dat Hij niet naar de orde van Aäron werd genoemd?',
        12: 'Met de verandering toch van het priesterschap verandert ook noodzakelijk de wet.',
        13: 'Welnu, Hij op wien dit alles slaat, behoorde tot een andere stam, waaruit niemand zich aan het altaar heeft gewijd;',
        14: 'want het is bekend, dat onze Heer uit Juda gesproten is; en met betrekking tot deze stam heeft Moses niets van priesters gesproken.',
        15: 'En dit is nog veel duidelijker, nu als evenbeeld van Melkisedek een ander Priester is aangesteld,',
        16: 'één, die het niet geworden is volgens de wet ener vleselijke instelling, maar uit kracht van een onvergankelijk leven;',
        17: 'want er is betuigd: "Gij zijt Priester voor eeuwig naar de Orde van Melkisedek."',
        18: 'En zó werd de vroegere instelling opgeheven om haar zwakte en nutteloosheid,',
        19: 'want de Wet heeft niets tot volmaking gebracht, —en werd ze vervangen door een betere hoop, waardoor wij naderen tot God.',
        20: 'Bovendien is dit ook niet zonder eed geschied. Want de anderen zijn priesters geworden zonder eed,',
        21: 'maar Hij werd het door een eed van Hem, die tot Hem sprak: "De Heer heeft gezworen, En het zal Hem nimmer berouwen: Gij zijt Priester voor eeuwig!"',
        22: 'En ook in zover is Jesus de borg geworden van een veel beter Verbond.',
        23: 'Daarenboven, die anderen zijn priesters geworden in grote getale, omdat ze door hun dood verhinderd werden aan te blijven.',
        24: 'Maar Hij bezit een onvervreemdbaar Priesterschap, omdat Hij blijft voor eeuwig.',
        25: 'Daarom kan Hij ook ten allen tijde hen redden, die tot God komen door zijn bemiddeling, daar Hij altijd leeft, om hun Middelaar te zijn.',
        26: 'Ons voegt ook een Hogepriester, die heilig is, onschuldig, onbezoedeld, verwijderd van de zondaars en verheven boven de hemelen;',
        27: 'Eén, die niet zoals de hogepriesters dagelijks nodig heeft, eerst voor eigen zonden te offeren, daarna voor die van het volk; want dit laatste heeft Hij eens en voor al gedaan door het Offer van Zichzelf.',
        28: 'De Wet toch stelt tot hogepriesters mensen aan, met zwakheid behept; maar de eed-uitspraak, die na de Wet is gekomen, den Zoon, die volmaakt is voor eeuwig.',
    },
    8: {
        1: 'Hoofdzaak echter van wat gesproken wordt, is het volgende: Een zo groot Hogepriester hebben we, dat Hij gezeten is ter rechterzijde van de troon der Majesteit in de hemelen,',
        2: 'en dat Hij Bedienaar is van het Heiligdom en van het ware Tabernakel, dat de Heer heeft opgericht, en niet een mens.',
        3: 'Want iedere hogepriester is aangesteld, om gaven en offers te brengen; daarom moet ook Hij iets hebben, om te offeren.',
        4: 'Welnu, indien Hij op aarde was, dan zou Hij zelfs niet eens priester zijn. Want daar zijn offeraars volgens de Wet,',
        5: 'en deze verrichten de dienst bij het afbeeldsel, de schaduw der hemelse dingen; zoals dit aan Moses, toen hij het tabernakel wilde vervaardigen, door een godsspraak werd duidelijk gemaakt, daar Hij sprak: "Zorg er voor, dat ge alles vervaardigt naar het model, dat u op de berg is getoond."',
        6: 'Maar thans heeft Hij een veel voortreffelijker bediening ontvangen, naarmate het Verbond, waarvan Hij Middelaar werd, volmaakter is, en op volmaaktere beloften rust.',
        7: 'Want zo het eerste zonder gebrek was geweest, dan zou er geen plaats zijn gezocht voor een tweede.',
        8: 'Maar Hij zegt, om hen te berispen: Ziet, de dagen komen, Spreekt de Heer, Dat Ik met het huis van Israël En met het huis van Juda Een nieuw Verbond zal sluiten.',
        9: 'Niet als het verbond, dat Ik met hun vaderen sloot, Toen Ik ze bij de hand heb gevat, Om ze uit het land van Egypte te leiden. Want zij deden mijn verbond niet gestand, En Ik bekommerde Mij niet over hen, Spreekt de Heer.',
        10: 'Maar dit is het Verbond, dat Ik sluit Met Israëls huis na deze dagen, spreekt de Heer. Mijn wetten zal Ik prenten in hun verstand, Ik zal ze schrijven op hun hart; En Ik zal hun God, Zij zullen mijn volk zijn!',
        11: 'Dan behoeven ze elkander niet meer te leren, De een tot den ander niet te zeggen: Leert den Heer kennen. Neen, dan zullen zij allen Mij kennen, Kleinen en groten;',
        12: 'Want dan zal Ik hun ongerechtigheden genadig zijn, Hun zonden niet langer gedenken.',
        13: 'Door van een nieuw Verbond te spreken, heeft Hij het vroegere verouderd verklaard; welnu, wat verouderd is en afgeleefd, is zijn opheffing nabij.',
    },
    9: {
        1: 'Ook het eerste verbond had voorschriften omtrent de eredienst en het aardse heiligdom.',
        2: 'Want er was een eerste tabernakel, waarin de kandelaar, de tafel en de toonbroden waren geplaatst; dit werd het Heilige genoemd.',
        3: 'Achter het tweede voorhangsel was een tabernakel, die het Heilige der Heiligen genoemd werd.',
        4: 'Dit bevatte naast een gouden reukaltaar ook de ark des verbonds, die geheel met goud was overtrokken, en waarin zich de gouden vaas met het manna bevond, benevens de staf van Aäron die gebloeid had, en de verbondstafelen;',
        5: 'en daarboven waren de cherubs der glorie, die het zoendeksel overschaduwden. Maar het is niet nodig, hierover thans in bijzonderheden uit te weiden.',
        6: 'En wanneer dit alles zó was ingericht, gingen de priesters ten allen tijde in de eerste tabernakel, om er de diensten te verrichten;',
        7: 'maar in de tweede alleen de hogepriester, en slechts éénmaal in het jaar en niet zonder het bloed, dat hij offerde voor zijn eigen nalatigheid en voor die van het volk.',
        8: 'Hiermee geeft de heilige Geest te verstaan, dat de weg tot het Heiligdom nog niet open staat, zolang de eerste tabernakel nog stand houdt,',
        9: 'die een afbeelding was van de tegenwoordige tijd. Vandaar dat er gaven en offers worden gebracht, welke den offeraar niet kunnen volmaken naar het geweten,',
        10: 'doch die tegelijk met spijzen, dranken en allerlei wassingen enkel vleselijke voorschriften zijn, vastgesteld tot aan de tijd van het volmaakte Bestel.',
        11: 'Maar Christus, optredend als Hogepriester der toekomende goederen, is het Heiligdom binnengegaan door de grotere en volmaaktere Tabernakel, welke niet met handen gemaakt is, —dat wil zeggen, welke niet tot deze schepping behoort;',
        12: 'niet door bloed van bokken en kalveren, maar door zijn eigen Bloed; ééns voor altijd, daar Hij een eeuwige verlossing verworven had.',
        13: 'Want zo het bloed van bokken en stieren, en de besprenkeling met as van een koe, de onreinen heiligt tot de reinheid van het vlees,',
        14: 'hoeveel te meer zal dan het Bloed van Christus, die door een eeuwigen Geest Zich als smetteloos Offer opdroeg aan God, ons geweten reinigen van dode werken tot de dienst van den levenden God?',
        15: 'En daarom is Hij de Middelaar van een nieuw Testament, en is Hij gestorven tot verzoening van de overtredingen van het eerste, opdat de uitverkorenen de beloofde eeuwige erfenis zouden ontvangen.',
        16: 'Want waar een testament is, daar moet de dood van den erflater worden vastgesteld.',
        17: 'Want het testament wordt eerst bindend door de dood, daar het niet van kracht is, zolang de erflater leeft.',
        18: 'Daarom ook is het eerste testament niet ingewijd zonder bloed.',
        19: 'Want nadat Moses alle voorschriften der Wet aan heel het volk had afgekondigd, nam hij het bloed van kalveren en bokken met water, purperwol en hysop, en besprenkelde het boek zelf en heel het volk,',
        20: 'terwijl hij sprak: "Dit is het bloed van het verbond, dat God met u heeft gesloten."',
        21: 'Eveneens besprenkelde hij de tabernakel en al het benodigde van de eredienst met het bloed;',
        22: 'ook wordt volgens de Wet nagenoeg alles door bloed gereinigd, en zonder bloedstorting is er geen vergiffenis.',
        23: 'Het was dus noodzakelijk, dat de afbeeldingen der hemelse dingen op die wijze werden gereinigd, maar de hemelse dingen zelf door volmaaktere offers.',
        24: 'Want Christus is niet een heiligdom binnengegaan, dat met handen gemaakt is en voorafbeelding is van het waarachtige, maar de hemel zelf, om thans voor Gods aangezicht te verschijnen ten behoeve van ons.',
        25: 'Ook droeg Hij Zich niet meermalen op, zoals de hogepriester ieder jaar opnieuw het heiligdom binnenging met het bloed, dat het zijne niet was.',
        26: 'Want dan zou Hij van de schepping der wereld af meermalen hebben moeten lijden, terwijl Hij feitelijk slechts éénmaal en op het einde der tijden verschenen is, om door zijn Offer de zonde te delgen.',
        27: 'En evenals het voor de mensen is vastgesteld, één enkele maal te sterven, en daarna het oordeel volgt,',
        28: 'zo is ook Christus één enkele maal geofferd, om veler zonden te delgen; en ten tweede male zal Hij verschijnen, niet om wille der zonde, maar tot zaligheid van hen, die Hem verwachten.',
    },
    10: {
        1: 'Daar de Wet slechts de schaduw bezit der toekomstige goederen en niet het wezen dier dingen zelf, kan ze onmogelijk door offers, welke men jaarlijks opdraagt op dezelfde wijze, hen die er aan deelnemen, ééns en voor al tot volmaaktheid brengen.',
        2: 'Zou anders het offeren niet hebben opgehouden, omdat dan de offeraars ééns en voor al waren gereinigd en zich geen zonden meer waren bewust?',
        3: 'Maar nu wordt integendeel ieder jaar de gedachte aan zonde opnieuw daardoor opgewekt.',
        4: 'Want het is onmogelijk, dat het bloed van stieren en bokken zonden wegneemt.',
        5: 'Daarom zegt Hij bij zijn Intreden in de wereld: Offers noch gaven hebt Gij gewild, Maar een Lichaam hebt Gij Mij bereid.',
        6: 'Brand- en zoenoffers behaagden U niet,',
        7: 'Toen zeide Ik: Zie Ik kom! In de boekrol staat van Mij geschreven, Uw wil te volbrengen, o God!',
        8: 'Daar Hij nu eerst heeft gezegd: "Offers en gaven, brand- en zoenoffers hebt Gij niet gewild, behaagden U niet," ofschoon ze volgens de Wet worden geofferd;',
        9: 'en Hij vervolgens sprak: "Zie Ik kom, om uw wil te volbrengen;" zó heeft Hij het eerste afgeschaft, om het tweede in te stellen.',
        10: 'Uit kracht van die wil zijn wij ééns en voor al geheiligd door het Offer van het Lichaam van Jesus Christus.',
        11: 'En terwijl iedere priester, dag in dag uit, dienst staat te verrichten en meermalen dezelfde offers opdraagt, welke toch nimmer de zonde kunnen wegnemen,',
        12: 'heeft Hij daarentegen, ééns en voor al, één enkel Offer gebracht voor de zonden, "en is Hij gezeten aan Gods rechterhand,"',
        13: 'in afwachting "tot zijn vijanden neergelegd zijn als voetbank voor zijn voeten."',
        14: 'Immers door één enkel Offer heeft Hij de geheiligden, ééns en voor al, tot volmaaktheid gebracht. Dit getuigt ons ook de heilige Geest.',
        15: 'Want nadat Hij gesproken heeft:',
        16: '"Dit is het Verbond, dat Ik sluit Met hen na deze dagen," Spreekt de Heer: Mijn wetten zal Ik prenten in hun harten, Ik zal ze schrijven in hun verstand;',
        17: 'En hun zonden en ongerechtigheden Zal Ik niet langer gedenken.',
        18: 'Welnu, waar deze vergeven zijn, daar is geen offer voor de zonde meer nodig.',
        19: 'Welnu dan broeders, daar we de vaste zekerheid hebben, dat door het Bloed van Jesus de weg tot het Heiligdom ons open staat,',
        20: '—een nieuwe en levende weg, die Hij ons heeft gebaand door het Voorhangsel heen, namelijk dat van zijn Vlees,',
        21: 'daar we eveneens "een Hogepriester over Gods Huis" hebben:',
        22: 'zo laat ons toetreden met een oprecht hart en in volle geloofsovertuiging; onze harten door besprenkeling gezuiverd van een slecht geweten, ons lichaam door rein water gewassen.',
        23: 'Laat ons onwrikbaar vasthouden aan de belijdenis der hoop; want Hij die de belofte deed, is getrouw.',
        24: 'Laat ons elkander gadeslaan, om ons tot liefde te prikkelen en goede werken;',
        25: 'verwaarloost het gemeenschapsleven niet, zoals sommigen plegen te doen; maar vermaant elkander, te meer, daar gij de Dag ziet naderen.',
        26: 'Want wanneer we, na de kennis der waarheid te hebben ontvangen, wetens en willens zondigen, dan is er geen offer voor de zonden meer in uitzicht,',
        27: 'maar slechts een vreselijke verwachting van oordeel en vuurgloed, die de weerspannigen zal verslinden.',
        28: 'Verwerpt iemand de Wet van Moses, zonder genade "sterft hij op het woord van twee of drie getuigen;"',
        29: 'hoeveel zwaarder straf, dunkt u, zal hij dan verdienen, die den Zoon van God met voeten treedt, het Bloed van het Verbond veracht, waardoor hij geheiligd is, en den Geest der genade durft honen?',
        30: 'We weten toch, dat Hij gezegd heeft: "Aan Mij is de wraak; Ik zal vergelden;" en eveneens: "de Heer zal zijn volk oordelen."',
        31: 'Vreselijk is het, te vallen in de handen van den levenden God.',
        32: 'Denkt eens terug aan de dagen, toen gij het licht hebt ontvangen, en daardoor zulk een smartelijke strijd hebt doorstaan:',
        33: 'nu eens zelf een toonbeeld van smaad en druk, dan weer één met hen, wie het zó verging.',
        34: 'Inderdaad, toen hebt gij mee geleden met hen, die gevangen waren, en de roof uwer goederen met blijdschap verdragen, in de overtuiging, dat gij betere en blijvende goederen bezit.',
        35: 'Werpt dus uw vast vertrouwen niet weg, dat een grote beloning in zich sluit.',
        36: 'Volharding toch is noodzakelijk voor u, om de wil van God te volbrengen en te verkrijgen wat beloofd is.',
        37: 'Want nog een kleine, kleine tijd: Hij die komt, zal komen, En Hij zal niet toeven.',
        38: 'Mijn rechtvaardige zal leven door geloof; Maar zo hij terugdeinst, Heeft mijn ziel geen behagen in hem.',
        39: 'Welnu, wij zijn geen mensen van terugdeinzen ten verderve, maar van geloven tot behoud onzer ziel.',
    },
    11: {
        1: 'Het geloof is een vaste grond voor wat men hoopt; een overtuiging over dingen, die men niet ziet.',
        2: 'Om het geloof zijn de Ouden met ere vermeld;',
        3: 'hierdoor ook erkennen we, dat de wereld door Gods Woord is geschapen, dat het zichtbare uit het Onzichtbare is ontstaan.',
        4: 'Door het geloof heeft Abel meer dan Kaïn aan God een voortreffelijk offer gebracht. Daardoor werd van hem getuigd, dat hij rechtvaardig was; want om zijn gave heeft God zelf dit betuigd. Door het geloof spreekt hij ook nog na zijn dood.',
        5: 'Door het geloof werd Henok opgenomen, zodat hij de dood niet heeft gezien; hij werd niet meer gevonden, omdat God hem opgenomen had. Want voordat hij opgenomen werd, is van hem getuigd, dat hij welgevallig was aan God.',
        6: 'Welnu, zonder geloof is het onmogelijk, welgevallig te zijn; want wie tot God wil naderen, moet geloven, dat Hij bestaat, en Beloner is voor hen, die Hem zoeken.',
        7: 'Door het geloof heeft Noë, toen hem geopenbaard werd, wat nog niet was te zien, dit ter harte genomen, en tot redding van zijn huis de ark gebouwd; waardoor hij de wereld veroordeelde, en deelachtig werd aan de gerechtigheid door het geloof.',
        8: 'Door het geloof ging Abraham, toen hij geroepen werd, gehoorzaam uit naar de plaats, die hij tot erfdeel zou ontvangen; hij vertrok. zonder te weten, waarheen hij ging.',
        9: 'Door het geloof vestigde hij zich in het land der beloften als in den vreemde, en woonde daar in tenten tezamen met Isaäk en Jakob, de medeërfgenamen derzelfde belofte;',
        10: 'want hij wachtte op de stad met grondslagen, wier kunstenaar en bouwheer God is.',
        11: 'Door het geloof heeft zelfs Sara, en nog wel boven de bepaalde leeftijd, de kracht tot zwangerschap ontvangen, omdat ze Hem, die het beloofd had, voor getrouw heeft gehouden.',
        12: 'Daarom ook is uit één man, en nog wel uit een, die afgeleefd was, een geslacht ontsproten, talrijk als de sterren aan de hemel en als het ontelbare zand aan het strand van de zee.',
        13: 'In het geloof zijn ze allen gestorven, zonder het beloofde te hebben ontvangen; maar ze hebben het slechts gezien en begroet uit de verte, en beleden, dat ze vreemdelingen zijn en zwervelingen op aarde.',
        14: 'Waarlijk, die zó iets zeggen, tonen wel degelijk, op zoek te zijn naar een vaderland.',
        15: 'En zo ze daarbij gedacht hadden aan het land, dat ze waren uitgetrokken, dan hadden ze tijd genoeg gehad, om daarheen terug te keren;',
        16: 'maar feitelijk hebben ze naar een beter gesmacht, naar het hemelse. Daarom schaamt God Zich niet, hun God te worden genoemd; want Hij heeft voor hen een stad bereid.',
        17: 'Door het geloof heeft Abraham, toen hij op de proef werd gesteld, Isaäk opgeofferd en zijn ééngeborene opgedragen,',
        18: 'ofschoon hij de belofte had ontvangen, en tot hem was gezegd: "In Isaäk zal uw naam worden voortgeplant."',
        19: 'Want hij was overtuigd, dat God machtig was, hem op te wekken zelfs uit de doden; vanwaar hij hem dan ook, om zo te zeggen, terug heeft ontvangen.',
        20: 'Door het geloof heeft Isaäk een zegening uitgesproken over Jakob en Esau, zelfs met betrekking tot de toekomstige dingen.',
        21: 'Door het geloof heeft de stervende Jakob beide zonen van Josef gezegend, en bad hij, steunend op de knop van zijn staf.',
        22: 'Door het geloof heeft Josef bij zijn sterven nog aan de uittocht der zonen Israëls gedacht, en bevelen gegeven met betrekking tot zijn gebeente.',
        23: 'Door het geloof werd Moses na zijn geboorte drie maanden lang door zijn ouders verborgen, daar ze zagen, "dat het knaapje schoon was;" en ze hebben het bevel van den koning niet gevreesd.',
        24: 'Door het geloof heeft Moses, toen hij groot was geworden, geweigerd, den zoon van Fárao’s dochter te heten,',
        25: 'en wilde hij liever smaad lijden met Gods volk dan een vergankelijk voordeel trekken uit de zonde;',
        26: 'hij stelde de smaad van Christus boven de schatten van Egypte, want hij hield het oog op de beloning gevestigd.',
        27: 'Door het geloof verliet hij Egypte zonder de toorn van den koning te vrezen; want hij stond pal, daar hij als het ware den Onzichtbare had gezien.',
        28: 'Door het geloof heeft hij het Pascha verordend en het bestrijken met bloed, opdat de verderver hun eerstgeborenen niet zou treffen.',
        29: 'Door het geloof zijn ze de Rode Zee doorgetrokken als door het droge; toen de Egyptenaren het beproefden, verdronken ze.',
        30: 'Door het geloof vielen de muren van Jéricho om na een rondgang van zeven dagen.',
        31: 'Door het geloof kwam de ontuchtige Rachab niet met de ongehoorzamen om, daar ze de verspieders in vrede ontving.',
        32: 'En wat zal ik nog zeggen? De tijd zou me ontbreken, zo ik verhalen ging van Gédeon, Barak, Samson, Jefte, David, Samuël en de Profeten.',
        33: 'Door het geloof hebben ze koninkrijken overweldigd, gerechtigheid uitgeoefend, beloften zien vervullen, leeuwenmuilen gestopt;',
        34: 'hebben ze het geweld van het vuur geblust, de scherpte van het zwaard kunnen ontgaan, nieuwe krachten na zwakheid bekomen, sterkte ontvangen in de strijd, heirscharen van vreemden doen wijken.',
        35: 'Vrouwen ontvingen haar doden door opstanding terug. Anderen lieten zich folteren en namen de vrijspraak niet aan, om een betere opstanding te bekomen.',
        36: 'Anderen weer leden bespotting en geseling, boeien zelfs en gevangenis;',
        37: 'ze werden gestenigd, door midden gezaagd, op de pijnbank beproefd, door het moordend zwaard gedood. Ze zwierven rond in schapenvachten en geitenvellen, verlaten, verdrukt en mishandeld:',
        38: 'de wereld was hunner niet waardig; dus doolden ze rond in woestijnen en bergen, spelonken en holen.',
        39: 'En toch heeft geen van hen de belofte in vervulling zien gaan. ofschoon ze om hun geloof met ere worden vermeld.',
        40: 'Want daar God voor ons iets beters beschikt had, mochten zij niet zonder ons tot verheerlijking komen.',
    },
    12: {
        1: 'Welnu dan, omringd van zulk een wolk van getuigen, laat ons iedere belemmering en hinder van zonde wegwerpen van ons, en dan met volharding de wedloop beginnen, die voor ons ligt;',
        2: 'het oog gevestigd op Jesus, aanvang en einde van het geloof. Hij heeft in plaats van de vreugde, die Hem toekwam, een kruis op Zich genomen, en de schande niet geacht; maar is dan ook gezeten ter rechterzijde van Gods troon.',
        3: 'Houdt Hem toch voor ogen, die van de zondaars zulk een tegenspraak heeft verduurd, opdat gij niet uitgeput raakt en de zielskracht verliest.',
        4: 'Nog hebt gij niet ten bloede toe weerstand geboden in de strijd tegen de zonde;',
        5: 'en zijt gij dan reeds de vermaning vergeten, die u als zonen toespreekt: Mijn zoon, verwerp de kastijding des Heren niet, En wees niet ontmoedigd, zo ge door Hem wordt bestraft.',
        6: 'Want de Heer kastijdt dien Hij bemint, Tuchtigt elken zoon, dien Hij liefheeft.',
        7: 'Verdraag het dus als een kastijding; God behandelt u als zonen. Want is er wel een zoon, die door zijn vader niet wordt gekastijd?',
        8: 'Zo gij dus zonder kastijding zoudt wezen, waarvan allen hun deel krijgen, dan waart gij bastaards en geen zonen.',
        9: 'Bovendien, we hebben vaders naar het vlees gehad, die ons kastijdden, en we kwamen tot inkeer; zullen we ons dan niet veel meer onderwerpen aan den Vader der geesten, en leven?',
        10: 'Zij toch hebben ons gekastijd ter wille van enkele dagen en naar het hun goeddacht; maar Hij doet het tot ons nut, opdat we zijn heiligheid deelachtig worden.',
        11: 'Elke kastijding schijnt op het ogenblik zelf geen reden tot vreugde, maar reden tot droefheid; later echter draagt ze hun, die er door geoefend zijn, een vredevrucht der gerechtigheid.',
        12: 'Richt op dus de slappe handen en knikkende knieën!',
        13: 'Maakt rechte sporen met uw voeten, opdat het kreupele niet wordt ontwricht, maar genezen veeleer!',
        14: 'Streeft naar vrede met allen; ook naar heiligheid, zonder welke niemand den Heer zal zien.',
        15: 'Zorgt er voor, dat niemand Gods genade verwaarloost; dat er geen wortel van bitterheid opschiet, anderen in de weg staat, en velen aansteekt;',
        16: 'dat niemand ontuchtig is, of onverschillig als Esau, die voor één enkele spijs zijn eerstgeboorterecht verkocht.',
        17: 'Gij weet toch, dat toen hij later de zegen wilde erven, hij afgewezen werd; want hij vond geen mogelijkheid, de gezindheid van zijn vader te veranderen, hoewel hij het onder tranen beproefde.',
        18: 'Inderdaad, gij zijt niet toegetreden tot een tastbare berg, niet tot brandend vuur, duisternis, donkere wolk, storm,',
        19: 'bazuingeschal; niet tot daverende woorden, waarvan de hoorders bezwoeren, dat er geen woord meer bij mocht komen,',
        20: 'omdat het bevel hun te machtig was: "Zelfs als een dier de berg aanraakt, moet het gestenigd worden."',
        21: 'En zó ontzettend was de verschijning, dat Moses uitriep: "Ik beef en sidder van angst."',
        22: 'Neen, gij zijt toegetreden tot de berg Sion en de Stad van den levenden God, het hemels Jerusalem; tot de tienduizenden engelen, tot de feestvergadering,',
        23: 'tot de gemeente der eerstgeborenen, opgeschreven in de hemel; tot God den Rechter van allen; tot de geesten der rechtvaardigen, die hun voleinding hebben bereikt;',
        24: 'tot Jesus den Middelaar van het nieuwe Verbond, tot het Bloed der besprenkeling, dat iets beters afroept dan Abels bloed.',
        25: 'Zorgt er voor, dat gij Hem niet afwijst, die roept! Want wanneer zij niet ontkwamen, die Hem afwezen, toen Hij op aarde sprak, hoeveel minder wij, zo we ons afkeren van Hem, die uit de hemelen spreekt,',
        26: 'wiens stem eertijds de aarde deed sidderen, maar die nu heeft verkondigd: "Nog eenmaal zal Ik doen beven Niet slechts de aarde, maar ook de hemel."',
        27: 'Welnu, dit "Nog eenmaal" wijst op de omverwerping van wat als schepsel vergankelijk is, opdat dan het onvergankelijke blijft bestaan.',
        28: 'Wij dus, die een onvergankelijk koninkrijk hebben ontvangen, we moeten vasthouden aan de genade, en daardoor God dienen, zoals het Hem welgevallig is: in vrome eerbied en ontzag.',
        29: 'Want onze God is een verterend vuur!',
    },
    13: {
        1: 'Laat er altijd broederlijke liefde blijven!',
        2: 'Verwaarloost ook de gastvrijheid niet; want daardoor hebben sommigen, zonder het te weten, engelen geherbergd.',
        3: 'Denkt aan de gevangenen, als waart gij medegevangen; aan hen, die mishandeld worden, als waart gijzelf in hun lichaam!',
        4: 'Het huwelijk moet eerbaar zijn onder ieder opzicht, en onbezoedeld het huwelijksbed; want God zal ontuchtigen en overspelers oordelen.',
        5: 'Weest niet hebzuchtig van aard, en stelt u tevreden met wat ge bezit; want Hij heeft gezegd: Ik zal u niet begeven,',
        6: 'Zo zeggen we met goede moed: "De Heer is mijn Helper; ik heb niets te vrezen; Wat kan een mens mij nog doen?"',
        7: 'Denkt aan uw leidslieden, die u het woord Gods hebben verkondigd; let op het einde van hun leven, en volgt hun geloof na.',
        8: 'Jesus Christus is Dezelfde, gisteren en heden en in eeuwigheid!',
        9: 'Laat u niet van de weg brengen door veelsoortige en vreemde leringen. Want goed is het, het hart door de genade te sterken, maar niet door spijzen, welke van geen nut zijn voor hen, die zich daaraan hechten.',
        10: 'We hebben een Altaar, waarvan zij, die de tabernakel bedienen, niet mogen eten.',
        11: 'Want de lichamen der dieren, wier bloed als een zoenoffer door den hogepriester in het heiligdom is gebracht, worden verbrand buiten de legerplaats.',
        12: 'Daarom heeft ook Jesus buiten de poort geleden, om het volk te heiligen door zijn Bloed.',
        13: 'Laat ons dus tot Hem uitgaan buiten de legerplaats en zijn smaad dragen;',
        14: 'want we hebben hier geen blijvende stad, maar we reikhalzen naar de toekomstige.',
        15: 'Door Hem moeten we een altijddurend dankoffer brengen aan God, namelijk de vrucht van lippen, die zijn Naam verheerlijken!',
        16: 'Vergeet de weldadigheid niet en de onderlinge hulp; want in zulke offers heeft God welbehagen.',
        17: 'Weest gehoorzaam en onderdanig aan uw leidslieden; want ze waken over uw zielen als mensen, die rekenschap hebben af te leggen. Zorgt er voor, dat ze dit met vreugde kunnen doen en niet met zuchten; want dat zou u niet voordelig zijn.',
        18: 'Bidt voor ons; want we vertrouwen, een rein geweten te hebben, daar we onder ieder opzicht ons onberispelijk trachten te gedragen.',
        19: 'Met meer nadruk verzoek ik u dit te doen, opdat ik u spoediger teruggegeven word.',
        20: 'De God van vrede, die Jesus onzen Heer van de doden heeft opgewekt, den groten Herder der schapen door het Bloed van een eeuwig Verbond:',
        21: 'Hij bevestige u in alle goed, opdat gij zijn wil moogt volbrengen; al wat Hem welbehagelijk is, werke Hij in ons uit door Jesus Christus: Hem zij ere in de eeuwen der eeuwen. Amen!',
        22: 'Ik bid u broeders, neemt het woord der vermaning gewillig aan! Want ik heb het u geschreven in een korte brief.',
        23: 'Gij weet, dat onze broeder Timóteus de vrijheid heeft verkregen. Zo hij spoedig komt, zal ik u bezoeken in zijn gezelschap.',
        24: 'Groet al uw leidslieden en alle heiligen. De Italianen groeten u.',
        25: 'De genade zij met u allen!',
    },
}
